          const brush = new T.Group(); brush.position.set(0.2, 1.0, 0); brush.rotation.z = -0.35; pot.add(brush); c.cyl(0.05, 0.05, 1.4, c.M(0xb07a4a), 0, 0.6, 0, brush, 8); c.cyl(0.09, 0.07, 0.14, c.M(0xc8c8d0, { metalness: 0.8 }), 0, -0.1, 0, brush, 8); c.cone(0.1, 0.35, c.M(cols[j % 4]), 0, -0.3, 0, brush, 8).rotation.x = PI;
